// Every app command is listed here so Tauri's permission system applies to it: a window can only
// call a command its capability file allows (src-tauri/capabilities/*.json). Without this list, any
// window could call any command. A new #[tauri::command] must be added here AND to a capability, or
// calls to it are refused ("not allowed by ACL").
//
// The permission files this generates (permissions/autogenerated/) are build output, not source.
const COMMANDS: &[&str] = &[
    // boot + window
    "boot_info",
    "relaunch",
    "confirm_native",
    // agent bridge (main window only; also checked in Rust)
    "bridge_ready",
    "bridge_reply",
    // d3d11 cost probe
    "probe_start",
    "probe_stop",
    // account + publishing
    "auth_sign_in",
    "auth_status",
    "auth_sign_out",
    "glslop_api",
    "glslop_publish",
    // the publish confirmation window (its own window only; also checked in Rust)
    "publish_view",
    "publish_decide",
    // files
    "fs_read_text",
    "fs_write_text",
    "fs_write_base64",
    "fs_write_bytes",
    "fs_list",
    "fs_mkdir",
    "fs_remove",
    "fs_exists",
];

fn main() {
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)))
        .expect("failed to run the tauri build script");
}
